sys_script.script:
(function executeRule(current, previous) {
    var orderedQty = parseFloat(current.getValue('ordered_quantity')) || 0;
    var receivedQty = parseFloat(current.getValue('received_quantity')) || 0;
    var rejectedQty = parseFloat(current.getValue('rejected_quantity')) || 0;
    var unitPrice = parseFloat(current.getValue('unit_price')) || 0;

    // ─────────────────────────────────────────────
    // VALIDATION 1: Ordered Quantity must be > 0
    // ─────────────────────────────────────────────
    if (orderedQty <= 0) {
        gs.addErrorMessage('Ordered Quantity must be greater than zero.');
        current.setAbortAction(true);
        return;
    }

    // ─────────────────────────────────────────────
    // VALIDATION 2: Received Quantity must be >= 0
    // ─────────────────────────────────────────────
    if (receivedQty < 0) {
        gs.addErrorMessage('Received Quantity cannot be negative.');
        current.setAbortAction(true);
        return;
    }

    // ─────────────────────────────────────────────
    // VALIDATION 3: Rejected Quantity must be >= 0
    // ─────────────────────────────────────────────
    if (rejectedQty < 0) {
        gs.addErrorMessage('Rejected Quantity cannot be negative.');
        current.setAbortAction(true);
        return;
    }

    // ─────────────────────────────────────────────
    // VALIDATION 4: Received + Rejected must not exceed Ordered
    // ─────────────────────────────────────────────
    if ((receivedQty + rejectedQty) > orderedQty) {
        gs.addErrorMessage(
            'Received (' + receivedQty + ') + Rejected (' + rejectedQty +
            ') = ' + (receivedQty + rejectedQty) +
            ' exceeds Ordered Quantity (' + orderedQty + ').'
        );
        current.setAbortAction(true);
        return;
    }

    // ─────────────────────────────────────────────
    // VALIDATION 5: Unit Price must be >= 0
    // ─────────────────────────────────────────────
    if (unitPrice < 0) {
        gs.addErrorMessage('Unit Price cannot be negative.');
        current.setAbortAction(true);
        return;
    }

    // ─────────────────────────────────────────────
    // CALCULATION: Remaining Quantity
    //   remaining = ordered - received - rejected
    // ─────────────────────────────────────────────
    var remaining = orderedQty - receivedQty - rejectedQty;
    current.setValue('remaining_quantity', Math.max(0, remaining));

    // ─────────────────────────────────────────────
    // CALCULATION: Line Total
    //   line_total = ordered_quantity × unit_price
    // ─────────────────────────────────────────────
    var lineTotal = orderedQty * unitPrice;
    // Round to 2 decimal places for currency precision
    lineTotal = Math.round(lineTotal * 100) / 100;
    current.setValue('line_total', lineTotal);

})(current, previous);
